def MC(sigma, epsilon, T, init_positions, MC_steps, dispSize):
    beta = 1 / T
    E_trace = []
    positions = np.copy(init_positions)
    for _ in range(MC_steps):
        i = np.random.randint(len(positions))
        new_position = positions[i] + np.random.normal(0, dispSize, 3)
        if np.linalg.norm(new_position) > sigma:
            continue
        E_new = U_system(np.append(positions[:i], new_position, axis=0), sigma, epsilon)
        E_old = U_system(positions, sigma, epsilon)
        acceptance_ratio = min(1, np.exp(-beta * (E_new - E_old)))
        if np.random.rand() < acceptance_ratio:
            positions[i] = new_position
        E_trace.append(U_system(positions, sigma, epsilon))
    return np.array(E_trace)

import numpy as np

def Nbody_Fij(xin, mass):
    G = 6.67430e-11
    N = len(mass)
    f = np.zeros((N, 3))

    for i in range(N):
        for j in range(i+1, N):
            r = np.linalg.norm(xin[j] - xin[i])
            f_i = G * mass[i] * mass[j] / (r ** 2) * (xin[j] - xin[i]) / r
            f[i] += f_i
            if i != j:
                f[j] -= f_i

    return f

import numpy as np

def Nbody_RK4(uin, mass, dt):
    def Nbody_RHS(u, t):
        N = len(mass)
        u = np.reshape(u, (N, 6))
        pos = u[:, :3]
        vel = u[:, 3:]
        acc = np.zeros_like(vel)

        for i in range(N):
            for j in range(i+1, N):
                r = pos[j] - pos[i]
                r_mag = np.linalg.norm(r)
                force = mass[i] * mass[j] / (r_mag ** 3) * r
                acc[i] += force
                acc[j] -= force

        return np.concatenate((vel, acc))

    uout = uin + dt/6 * (
        Nbody_RHS(uin, 0) +
        2*Nbody_RHS(uin + dt/2 * Nbody_RHS(uin, 0), dt/2) +
        2*Nbody_RHS(uin + dt/2 * Nbody_RHS(uin + dt/2 * Nbody_RHS(uin, 0), dt/2), dt/2) +
        Nbody_RHS(uin + dt * Nbody_RHS(uin + dt/2 * Nbody_RHS(uin + dt/2 * Nbody_RHS(uin, 0), dt/2), dt), dt)
    )

    return uout.reshape(-1)

