        if k == 1:
            hks.append(cmath.real(hamiltonian[0][1]))
        elif k == 2:
            hks.append(-cmath.imag(hamiltonian[0][1]))
        elif k == 3:
            hks.append((hamiltonian[0][0] - hamiltonian[1][1]) / 2)
        elif k == 4:
            hks.append(cmath.real(hamiltonian[0][2]))
        elif k == 5:
            hks.append(-cmath.imag(hamiltonian[0][2]))
        elif k == 6:
            hks.append(cmath.real(hamiltonian[1][2]))
        elif k == 7:
            hks.append(-cmath.imag(hamiltonian[1][2]))
